using System;using System.Linq;using UnityEngine;
public static class RenderComboPreparation{
public static object Run(){var root=UnityEngine.Object.Instantiate(GameObject.Find("New Knight Combo Sequence Preview"));root.transform.SetPositionAndRotation(new Vector3(1000,0,1000),Quaternion.identity);var a=root.GetComponentInChildren<Animator>();a.enabled=false;var c=a.runtimeAnimatorController.animationClips[0];var hip=root.GetComponentsInChildren<Transform>().First(t=>t.name=="Hips");var go=new GameObject("Step review camera");var cam=go.AddComponent<Camera>();cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=new Color(.24f,.26f,.29f);cam.fieldOfView=40;var rt=new RenderTexture(280,380,24);cam.targetTexture=rt;var tex=new Texture2D(1680,1140,TextureFormat.RGB24,false);var old=RenderTexture.active;int[] ends={16,43,90,131,153,173};try{for(int col=0;col<6;col++){c.SampleAnimation(a.gameObject,(ends[col]+3)/30f);var target=hip.position+Vector3.up*.12f;cam.transform.position=target+new Vector3(-2.8f,1.3f,3.5f);cam.transform.LookAt(target);for(int row=0;row<3;row++){c.SampleAnimation(a.gameObject,(ends[col]+row*3)/30f);cam.Render();RenderTexture.active=rt;tex.ReadPixels(new Rect(0,0,280,380),col*280,(2-row)*380);}}tex.Apply();System.IO.File.WriteAllBytes("Assets/3DBattle/Authoring~/ComboPreparationReview.png",tex.EncodeToPNG());return "saved";}finally{RenderTexture.active=old;cam.targetTexture=null;UnityEngine.Object.DestroyImmediate(root);UnityEngine.Object.DestroyImmediate(go);UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(tex);}}}
